import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Button,
  Box,
  Grid,
  Card,
  CardContent,
  CardMedia,
  Chip,
  IconButton,
  Fade,
  Slide
} from '@mui/material';
import { 
  useNavigate 
} from 'react-router-dom';
import { 
  ShoppingBag, 
  TrendingUp, 
  LocalOffer,
  ArrowBackIos,
  ArrowForwardIos,
  Star,
  LocalShipping,
  Security,
  Support
} from '@mui/icons-material';

const HomePage = () => {
  const navigate = useNavigate();
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isVisible, setIsVisible] = useState({});

  const heroSlides = [
    {
      id: 1,
      title: 'Summer Collection 2024',
      subtitle: 'Discover the hottest trends',
      description: 'Light, comfortable, and stylish pieces for the perfect summer wardrobe',
      image: 'https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?w=800&h=400&fit=crop',
      buttonText: 'Shop Summer',
      color: '#FF6B35'
    },
    {
      id: 2,
      title: 'Premium Denim Collection',
      subtitle: 'Crafted to perfection',
      description: 'High-quality denim pieces that combine comfort with contemporary style',
      image: 'https://images.unsplash.com/photo-1542272604-787c3835535d?w=800&h=400&fit=crop',
      buttonText: 'Explore Denim',
      color: '#4A90E2'
    },
    {
      id: 3,
      title: 'Accessories & More',
      subtitle: 'Complete your look',
      description: 'From bags to jewelry, find the perfect accessories to express your style',
      image: 'https://images.unsplash.com/photo-1469334031218-e382a71b716b?w=800&h=400&fit=crop',
      buttonText: 'Shop Accessories',
      color: '#9B59B6'
    }
  ];

  // Auto-slide effect
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % heroSlides.length);
    }, 5000);
    return () => clearInterval(timer);
  }, [heroSlides.length]);

  // Intersection Observer for animations
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsVisible(prev => ({ ...prev, [entry.target.id]: true }));
          }
        });
      },
      { threshold: 0.1 }
    );

    const elements = document.querySelectorAll('[data-animate]');
    elements.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  const nextSlide = () => {
    setCurrentSlide((prev) => (prev + 1) % heroSlides.length);
  };

  const prevSlide = () => {
    setCurrentSlide((prev) => (prev - 1 + heroSlides.length) % heroSlides.length);
  };

  const featuredCategories = [
    {
      id: 1,
      name: 'Men\'s Fashion',
      image: 'https://images.unsplash.com/photo-1516826957135-700dedea698c?w=400',
      description: 'Trendy outfits for modern men'
    },
    {
      id: 2,
      name: 'Women\'s Fashion',
      image: 'https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?w=400',
      description: 'Elegant styles for every occasion'
    },
    {
      id: 3,
      name: 'Accessories',
      image: 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=400',
      description: 'Complete your look with perfect accessories'
    }
  ];

  return (
    <Box>
      {/* Hero Slider Section */}
      <Box
        sx={{
          position: 'relative',
          height: { xs: '60vh', md: '80vh' },
          overflow: 'hidden',
          mb: 6
        }}
      >
        {heroSlides.map((slide, index) => (
          <Fade key={slide.id} in={index === currentSlide} timeout={1000}>
            <Box
              sx={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                backgroundImage: `linear-gradient(rgba(0,0,0,0.4), rgba(0,0,0,0.4)), url(${slide.image})`,
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                display: 'flex',
                alignItems: 'center',
                color: 'white'
              }}
            >
              <Container maxWidth="lg">
                <Grid container alignItems="center" spacing={4}>
                  <Grid item xs={12} md={6}>
                    <Slide direction="right" in={index === currentSlide} timeout={800}>
                      <Box>
                        <Typography
                          variant="h6"
                          sx={{
                            color: slide.color,
                            fontWeight: 600,
                            mb: 2,
                            textTransform: 'uppercase',
                            letterSpacing: 2
                          }}
                        >
                          {slide.subtitle}
                        </Typography>
                        <Typography
                          variant="h2"
                          sx={{
                            fontWeight: 800,
                            mb: 3,
                            fontSize: { xs: '2.5rem', md: '3.5rem' },
                            lineHeight: 1.2
                          }}
                        >
                          {slide.title}
                        </Typography>
                        <Typography
                          variant="h6"
                          sx={{
                            mb: 4,
                            opacity: 0.9,
                            maxWidth: '500px',
                            lineHeight: 1.6
                          }}
                        >
                          {slide.description}
                        </Typography>
                        <Button
                          variant="contained"
                          size="large"
                          onClick={() => navigate('/products')}
                          sx={{
                            backgroundColor: slide.color,
                            px: 4,
                            py: 1.5,
                            fontSize: '1.1rem',
                            fontWeight: 600,
                            borderRadius: 2,
                            boxShadow: `0 8px 25px ${slide.color}40`,
                            transition: 'all 0.3s ease',
                            '&:hover': {
                              backgroundColor: slide.color,
                              transform: 'translateY(-2px)',
                              boxShadow: `0 12px 35px ${slide.color}60`
                            }
                          }}
                          startIcon={<ShoppingBag />}
                        >
                          {slide.buttonText}
                        </Button>
                      </Box>
                    </Slide>
                  </Grid>
                </Grid>
              </Container>
            </Box>
          </Fade>
        ))}

        {/* Navigation Arrows */}
        <IconButton
          onClick={prevSlide}
          sx={{
            position: 'absolute',
            left: 20,
            top: '50%',
            transform: 'translateY(-50%)',
            backgroundColor: 'rgba(255, 255, 255, 0.2)',
            color: 'white',
            '&:hover': {
              backgroundColor: 'rgba(255, 255, 255, 0.3)',
              transform: 'translateY(-50%) scale(1.1)'
            },
            transition: 'all 0.3s ease',
            zIndex: 2
          }}
        >
          <ArrowBackIos />
        </IconButton>
        <IconButton
          onClick={nextSlide}
          sx={{
            position: 'absolute',
            right: 20,
            top: '50%',
            transform: 'translateY(-50%)',
            backgroundColor: 'rgba(255, 255, 255, 0.2)',
            color: 'white',
            '&:hover': {
              backgroundColor: 'rgba(255, 255, 255, 0.3)',
              transform: 'translateY(-50%) scale(1.1)'
            },
            transition: 'all 0.3s ease',
            zIndex: 2
          }}
        >
          <ArrowForwardIos />
        </IconButton>

        {/* Slide Indicators */}
        <Box
          sx={{
            position: 'absolute',
            bottom: 30,
            left: '50%',
            transform: 'translateX(-50%)',
            display: 'flex',
            gap: 1,
            zIndex: 2
          }}
        >
          {heroSlides.map((_, index) => (
            <Box
              key={index}
              onClick={() => setCurrentSlide(index)}
              sx={{
                width: 12,
                height: 12,
                borderRadius: '50%',
                backgroundColor: index === currentSlide ? 'white' : 'rgba(255, 255, 255, 0.5)',
                cursor: 'pointer',
                transition: 'all 0.3s ease',
                '&:hover': {
                  backgroundColor: 'white',
                  transform: 'scale(1.2)'
                }
              }}
            />
          ))}
        </Box>
      </Box>

      <Container maxWidth="xl" sx={{ py: 4 }}>

      {/* Features Section */}
      <Box 
        id="features" 
        data-animate 
        sx={{ 
          mb: 8,
          opacity: isVisible.features ? 1 : 0,
          transform: isVisible.features ? 'translateY(0)' : 'translateY(50px)',
          transition: 'all 0.8s ease'
        }}
      >
        <Typography 
          variant="h3" 
          textAlign="center" 
          gutterBottom 
          fontWeight="bold"
          sx={{
            background: 'linear-gradient(45deg, #667eea, #764ba2)',
            backgroundClip: 'text',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
            mb: 6
          }}
        >
          Why Choose Us?
        </Typography>
        <Grid container spacing={4} sx={{ mt: 2 }}>
          {[
            {
              icon: <LocalShipping fontSize="large" />,
              title: 'Free Shipping',
              description: 'Free shipping on orders over $50. Fast and reliable delivery worldwide',
              color: '#FF6B35',
              delay: 0
            },
            {
              icon: <Security fontSize="large" />,
              title: 'Secure Payment',
              description: '100% secure payment processing with SSL encryption and fraud protection',
              color: '#4A90E2',
              delay: 200
            },
            {
              icon: <Support fontSize="large" />,
              title: '24/7 Support',
              description: 'Round-the-clock customer support via chat, email, and phone',
              color: '#9B59B6',
              delay: 400
            },
            {
              icon: <Star fontSize="large" />,
              title: 'Premium Quality',
              description: 'Carefully curated products from top brands with quality guarantee',
              color: '#F39C12',
              delay: 600
            }
          ].map((feature, index) => (
            <Grid item xs={12} sm={6} lg={3} key={index}>
              <Card 
                sx={{ 
                  textAlign: 'center', 
                  p: 3, 
                  height: '100%',
                  borderRadius: 3,
                  border: 'none',
                  boxShadow: '0 10px 30px rgba(0,0,0,0.1)',
                  transition: 'all 0.4s ease',
                  cursor: 'pointer',
                  '&:hover': {
                    transform: 'translateY(-10px)',
                    boxShadow: `0 20px 40px ${feature.color}30`,
                    '& .feature-icon': {
                      transform: 'scale(1.2) rotate(5deg)',
                      color: feature.color
                    }
                  }
                }}
              >
                <Box 
                  className="feature-icon"
                  sx={{ 
                    color: feature.color, 
                    mb: 2,
                    transition: 'all 0.3s ease',
                    display: 'inline-block'
                  }}
                >
                  {feature.icon}
                </Box>
                <Typography 
                  variant="h6" 
                  gutterBottom 
                  fontWeight="bold"
                  sx={{
                    color: '#2c3e50',
                    mb: 2
                  }}
                >
                  {feature.title}
                </Typography>
                <Typography 
                  variant="body2" 
                  color="text.secondary"
                  sx={{
                    lineHeight: 1.6
                  }}
                >
                  {feature.description}
                </Typography>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Box>

      {/* Featured Categories */}
      <Box 
        id="categories" 
        data-animate 
        sx={{ 
          mb: 8,
          opacity: isVisible.categories ? 1 : 0,
          transform: isVisible.categories ? 'translateY(0)' : 'translateY(50px)',
          transition: 'all 0.8s ease 0.2s'
        }}
      >
        <Typography 
          variant="h3" 
          textAlign="center" 
          gutterBottom 
          fontWeight="bold"
          sx={{
            background: 'linear-gradient(45deg, #667eea, #764ba2)',
            backgroundClip: 'text',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
            mb: 2
          }}
        >
          Featured Categories
        </Typography>
        <Typography 
          variant="h6" 
          textAlign="center" 
          color="text.secondary" 
          paragraph
          sx={{
            maxWidth: '600px',
            mx: 'auto',
            mb: 6
          }}
        >
          Explore our curated collections designed for every style and occasion
        </Typography>
        <Grid container spacing={4} sx={{ mt: 2 }}>
          {featuredCategories.map((category, index) => (
            <Grid item xs={12} sm={6} md={4} key={category.id}>
              <Card 
                sx={{ 
                  cursor: 'pointer',
                  borderRadius: 3,
                  overflow: 'hidden',
                  position: 'relative',
                  transition: 'all 0.4s ease',
                  '&:hover': {
                    transform: 'translateY(-8px) scale(1.02)',
                    boxShadow: '0 25px 50px rgba(0,0,0,0.2)',
                    '& .category-image': {
                      transform: 'scale(1.1)'
                    },
                    '& .category-overlay': {
                      opacity: 1
                    }
                  }
                }}
                onClick={() => navigate(`/products?category=${category.name.toLowerCase()}`)}
              >
                <Box sx={{ position: 'relative', overflow: 'hidden' }}>
                  <CardMedia
                    className="category-image"
                    component="img"
                    height="250"
                    image={category.image}
                    alt={category.name}
                    sx={{
                      transition: 'transform 0.4s ease'
                    }}
                  />
                  <Box
                    className="category-overlay"
                    sx={{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      right: 0,
                      bottom: 0,
                      background: 'linear-gradient(45deg, rgba(102, 126, 234, 0.8), rgba(118, 75, 162, 0.8))',
                      opacity: 0,
                      transition: 'opacity 0.3s ease',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center'
                    }}
                  >
                    <Typography
                      variant="h5"
                      color="white"
                      fontWeight="bold"
                      sx={{
                        textAlign: 'center',
                        textShadow: '0 2px 4px rgba(0,0,0,0.3)'
                      }}
                    >
                      Shop Now
                    </Typography>
                  </Box>
                </Box>
                <CardContent
                  sx={{
                    background: 'linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%)',
                    position: 'relative'
                  }}
                >
                  <Typography 
                    variant="h5" 
                    gutterBottom 
                    fontWeight="bold"
                    sx={{
                      color: '#2c3e50',
                      mb: 1
                    }}
                  >
                    {category.name}
                  </Typography>
                  <Typography 
                    variant="body2" 
                    color="text.secondary"
                    sx={{
                      lineHeight: 1.6,
                      mb: 2
                    }}
                  >
                    {category.description}
                  </Typography>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Chip 
                      label="Explore" 
                      sx={{
                        background: 'linear-gradient(45deg, #667eea, #764ba2)',
                        color: 'white',
                        fontWeight: 600,
                        '&:hover': {
                          background: 'linear-gradient(45deg, #764ba2, #667eea)',
                          transform: 'scale(1.05)'
                        },
                        transition: 'all 0.2s ease'
                      }}
                      size="small" 
                    />
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Box>

      {/* Call to Action */}
      <Box
        id="cta"
        data-animate
        sx={{
          textAlign: 'center',
          py: 8,
          background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
          borderRadius: 4,
          color: 'white',
          position: 'relative',
          overflow: 'hidden',
          opacity: isVisible.cta ? 1 : 0,
          transform: isVisible.cta ? 'translateY(0)' : 'translateY(50px)',
          transition: 'all 0.8s ease 0.4s',
          '&::before': {
            content: '""',
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'url("data:image/svg+xml,%3Csvg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg"%3E%3Cg fill="%23ffffff" fill-opacity="0.05"%3E%3Cpath d="M20 20c0 11.046-8.954 20-20 20v20h40V20c0-11.046-8.954-20-20-20z"/%3E%3C/g%3E%3C/svg%3E")',
            pointerEvents: 'none'
          }
        }}
      >
        <Box sx={{ position: 'relative', zIndex: 1 }}>
          <Typography 
            variant="h3" 
            gutterBottom 
            fontWeight="bold"
            sx={{
              textShadow: '0 2px 4px rgba(0,0,0,0.3)',
              mb: 3
            }}
          >
            Ready to Start Shopping?
          </Typography>
          <Typography 
            variant="h6" 
            paragraph 
            sx={{
              opacity: 0.95,
              maxWidth: '600px',
              mx: 'auto',
              mb: 4,
              lineHeight: 1.6
            }}
          >
            Join thousands of satisfied customers and discover your perfect style with our premium collection
          </Typography>
          <Button
            variant="contained"
            size="large"
            onClick={() => navigate('/products')}
            sx={{
              backgroundColor: 'white',
              color: '#667eea',
              px: 6,
              py: 2,
              fontSize: '1.2rem',
              fontWeight: 700,
              borderRadius: 3,
              boxShadow: '0 8px 25px rgba(0,0,0,0.2)',
              transition: 'all 0.3s ease',
              '&:hover': {
                backgroundColor: '#f8f9fa',
                transform: 'translateY(-3px)',
                boxShadow: '0 15px 35px rgba(0,0,0,0.3)'
              }
            }}
            startIcon={<ShoppingBag />}
          >
            Browse All Products
          </Button>
        </Box>
      </Box>
      </Container>
    </Box>
  );
};

export default HomePage;
